<div class="push-preferences"><button class="btn" type="button" data-push-toggle data-push-scope="{{ $pushScope }}" data-push-prepare="{{ route($pushScope === 'admin' ? 'admin.account.push.prepare' : 'push.prepare') }}" data-push-store="{{ route($pushScope === 'admin' ? 'admin.account.push.store' : 'push.store') }}" data-push-delete="{{ route($pushScope === 'admin' ? 'admin.account.push.destroy' : 'push.destroy') }}">Activer / désactiver les notifications sur cet appareil</button><p class="hint" data-push-feedback role="status"></p></div>
